import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"42、【益】 震下巽上","description":"周易口诀义 - 42、【益】 震下巽上","frontmatter":{"title":"42、【益】 震下巽上","description":"周易口诀义 - 42、【益】 震下巽上"},"headers":[],"relativePath":"zh/classics/koujueyi/044.md","filePath":"zh/classics/koujueyi/044.md"}'),r={name:"zh/classics/koujueyi/044.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_42、【益】-震下巽上" tabindex="-1">42、【益】 震下巽上 <a class="header-anchor" href="#_42、【益】-震下巽上" aria-label="Permalink to “42、【益】 震下巽上”">​</a></h1><p>彖曰：益，损上益下，民说无疆。自上下下，其道大光。「利有攸往」，中正有庆。「利涉大川」，木道乃行。益动而巽，日进无疆。天施地生，其益无方。凡益之道，与时偕行。</p><p>象曰：风雷，益。君子以见善则迁，有过则改。</p><p>初九：利用为大作，元吉，无咎。</p><p>象曰：「元吉无咎」，下不厚事也。</p><p>六二：或益之十朋之龟，弗克违，永贞吉。王用享于帝，吉。</p><p>象曰：「或益之」，自外来也。</p><p>六三：益之用凶事，无咎。有孚中行，告公用圭。</p><p>象曰：益用凶事，固有之也。</p><p>六四：中行告公从，利用为依迁国。</p><p>象曰：「告公从」，以益志也。</p><p>九五：有孚惠心，勿问，元吉。有孚惠我德。象曰：「有孚惠心」，勿问之矣；「惠我德」，大得志也。</p><p>上九：莫益之，或击之，立心勿恒，凶。</p><p>象曰：「莫益之」，偏辞也；「或击之」，自外来也。</p><p>解读</p><p>益「利有攸往」者，益是增长之名，饶裕为义也。损卦损下益上，益卦损上益下者，亦犹人君能自损己而惠下人。故宋衷云：「明君之德，必须损己而利人，则下尽益矣。」君能以益物为意，动而无有违者，即斯而往，何所不利？故曰「利有攸往」也。利涉大川者，能益于物，则理绝难险，故「利涉大川」也。象曰「风雷，益」者，雷以发生，风能长育，万物皆益，故益之为义，在雷风也。君子以见善则迁，有过则改。迁，进移也；改，更惩也。君子求益，莫过迁进，企慕道德，其有过恶，改更惩戒，不再为也。</p><p>初九「利用为大作，元吉，无咎」者，处益之初，应巽之始，体刚干事，能堪建大事之端，以成王事者也。然虽有其才而得其时，不居其位，即时人不辅，欲有兴作，即祸必生焉，必须有大功以补其过，即得无咎，故曰「元吉，无咎」。元吉是有功之词，「大作」谓兴作大事也。</p><p>六二或益之十朋之龟，弗克违，永贞吉。王用享于帝，吉者，以柔居中，又应于巽，处益而怀巽，即物皆归焉，故曰「或益之」。朋，众也；龟，灵鉴也。六二既怀谦冲，即物自外来，朋灵献策，群才响应，故「十朋之龟，弗克违」也。然位不当尊，故「永贞吉」也。处益如斯，上下归德，故王用此时，可以享献天帝，即朋灵降福，故曰「王用享于帝，吉」也。</p><p>六三，益之用凶事，无咎。「有孚中行，告公用圭」者，以阴居阳，以刚健而求于益，故曰「益之」。不能行谦而用刚壮求益，即物所不与。若以谦让责之，理合诛讨；若以意测，原本情，志在救难，即物皆恃之，是「用凶事」而得免咎，故曰「用凶事，无咎」也。若乃求益不为私己，志在救难，用壮不至刚暴，斯乃适合时宜，是有信实而得中行，此中行之道，执圭以告于公，救凶危之事，故曰「有孚中行，告公用圭」也。</p><p>六四，「中行告公从，利用为依迁国」者，以柔处臣位，居巽之初，在上应下，位虽不中，用中而行，故曰「中行」。与君相近，即是藩屏之臣。以此中行之道而告于公，公必从之。以此道依人而迁，国人无不顺；明以中行之道而迁国，人无不利矣，故曰「利用为依迁国」也。</p><p>九五：有孚惠心，勿问元吉。「有孚惠我德」者，得位处尊，为益之主，兼张德义。德义之本，莫盛乎信；为益之大，莫大于心，因人所欲而己。与人有信有惠，尽物之心，益之盛矣。既有斯德，必获大吉，不假疑问，德必昭彰，故曰「有孚惠心，勿问元吉」。我既以信惠被于物，则天下皆以信惠归我，故「有孚惠我德」也。</p><p>上九：莫益之，或击之，立心勿恒，凶者，处益之极，益之甚也。既已过盈，即人之不与，故曰「莫益之」也。无厌之求，怨怒非一，故曰「或击之」也。勿，无也。益以过极而更有求，是立心无恒，凶祸必至，故曰「立心勿恒，凶」也。周易口诀义卷四，</p>',22)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
